INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist freie Software immer kostenlos?', 2, '[{"text": "Nein", "correct": true, "because": "Kosten für Support oder Anpassungen möglich"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig kostenfrei"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptvorteil, wenn ich solche Software einsetze?', 3, '[{"text": "Transparenz", "correct": true, "because": "Quellcode ist einsehbar"}, {"text": "Hohe Lizenzkosten", "correct": false, "because": "Meist keine Lizenzgebühren"}, {"text": "Manuelle Updates", "correct": false, "because": "Automatisierung üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale machen solche Software besonders?', 5, '[{"text": "Offener Quellcode", "correct": true, "because": "Erlaubt Anpassungen"}, {"text": "Community-Unterstützung", "correct": true, "because": "Fördert Entwicklung"}, {"text": "Proprietäre Lizenz", "correct": false, "because": "Gegenteil von Open Source"}, {"text": "Eingeschränkte Nutzung", "correct": false, "because": "Frei nutzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Freie Software erlaubt Modifikationen. b) Sie ist immer sicherer als proprietäre.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) hängt von Umsetzung ab"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Auswahl solcher Software?', 4, '[{"text": "Community-Aktivität", "correct": false, "because": "Zeigt Support-Level"}, {"text": "Lizenzbedingungen", "correct": false, "because": "Regeln Nutzung"}, {"text": "Farbschema", "correct": true, "because": "Irrelevant für Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob solche Software immer für Unternehmen geeignet ist?', 2, '[{"text": "Ja", "correct": true, "because": "Viele Unternehmen nutzen sie"}, {"text": "Nein", "correct": false, "because": "Breit einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Kriterium ist bei der Wahl solcher Software entscheidend?', 3, '[{"text": "Aktive Entwicklung", "correct": true, "because": "Sichert Updates"}, {"text": "Hohe Grafikleistung", "correct": false, "because": "Nicht primär"}, {"text": "Manuelle Installation", "correct": false, "because": "Automatisierung üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet freie Software?', 5, '[{"text": "Kosteneinsparung", "correct": true, "because": "Keine Lizenzgebühren"}, {"text": "Flexibilität", "correct": true, "because": "Anpassbarer Code"}, {"text": "Exklusiver Support", "correct": false, "because": "Support oft kostenpflichtig"}, {"text": "Feste Versionen", "correct": false, "because": "Regelmäßige Updates"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Solche Software hat oft MIT-Lizenzen. b) Sie ist immer fehlerfrei. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist nicht garantiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für den Einsatz solcher Software?', 4, '[{"text": "Dokumentation", "correct": false, "because": "Hilft bei Nutzung"}, {"text": "Kompatibilität", "correct": false, "because": "Sichert Integration"}, {"text": "Proprietäre Lizenzen", "correct": true, "because": "Nicht erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist freie Software nur für Entwickler gedacht?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Endnutzer geeignet"}, {"text": "Ja", "correct": false, "because": "Breite Zielgruppe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Lizenztypen sind typisch für solche Software?', 4, '[{"text": "GPL", "correct": true, "because": "Fördert freie Weitergabe"}, {"text": "MIT", "correct": true, "because": "Erlaubt flexible Nutzung"}, {"text": "EULA", "correct": false, "because": "Proprietär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass solche Software immer unsicher ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Sicherheit durch Community-Prüfung"}, {"text": "Ja", "correct": false, "because": "Sicherheit variiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Auswahl solcher Software?', 3, '[{"text": "Langfristige Unterstützung", "correct": true, "because": "Sichert Updates"}, {"text": "Maximale Geschwindigkeit", "correct": false, "because": "Sekundär"}, {"text": "Manuelle Anpassung", "correct": false, "because": "Automatisierung besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Freie Software fördert Zusammenarbeit. b) Sie erfordert immer Programmierkenntnisse.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist nicht zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen gibt es bei solcher Software?', 5, '[{"text": "Supportabhängigkeit", "correct": true, "because": "Oft Community-basiert"}, {"text": "Kompatibilitätsprobleme", "correct": true, "because": "Nicht immer standardisiert"}, {"text": "Hohe Lizenzkosten", "correct": false, "because": "Meist kostenfrei"}, {"text": "Feste Versionen", "correct": false, "because": "Regelmäßige Updates"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Nutzung solcher Software unwichtig?', 3, '[{"text": "Dokumentation", "correct": false, "because": "Hilft bei Nutzung"}, {"text": "Updates", "correct": false, "because": "Sichern Funktionalität"}, {"text": "Bildbearbeitung", "correct": true, "because": "Kein Softwaremerkmal"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist freie Software immer plattformübergreifend?', 3, '[{"text": "Nein", "correct": true, "because": "Hängt von Software ab"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob solche Software für kritische Systeme geeignet ist?', 2, '[{"text": "Ja", "correct": true, "because": "Wird in Servern genutzt"}, {"text": "Nein", "correct": false, "because": "Breit einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zur Nutzung solcher Software?', 4, '[{"text": "Entwicklung eines Webservers", "correct": true, "because": "Apache ist Open Source"}, {"text": "Proprietäre Datenbank", "correct": false, "because": "Eher geschlossen"}, {"text": "3D-Animation", "correct": false, "because": "Spezialisierte Software"}]');
